// BlackHalo disclosure site — no build step, runs as-is on GitHub Pages.
// Data under data/ is generated by the private vault (scripts/bh.mjs publish):
//   stats.json · embargo.json · index/<year>.json · details/<year>/<date>.json
import { marked } from "./vendor/marked.esm.js";
import DOMPurify from "./vendor/purify.es.js";
import { describeVector, severityOf } from "./cvss.js";

/* ---------- configuration: the only block you normally edit ---------- */
const SITE = {
  repo: "gpheheise/blackhalo",   // repository that hosts this site
  branch: "main",
  owner: "gpheheise",            // GitHub user or organisation that owns the research repositories
  data: "data/",
  localWriteups: "writeups/",    // fallback folder in this repo, used when a research repo is private or unreachable
  fetchTimeoutMs: 7000,
};
const DAY = 86_400_000;
const WINDOW_DAYS = 90;
const INDEX_PAGE = 48;
const BOARD_PAGE = 24;

const SEVERITIES = ["Critical", "High", "Medium", "Low"];
const CLASS_SHORT = {
  "Remote Code Execution": "RCE", "Authentication Bypass": "Auth bypass", "Server-Side Request Forgery": "SSRF",
  "Insecure Deserialization": "Deserialization", "Cross-Site Scripting": "XSS", "Path Traversal": "Path traversal",
  "SQL Injection": "SQL injection", "Privilege Escalation": "Privilege escalation", "XML External Entity": "XXE",
  "Information Disclosure": "Info disclosure", "Cross-Site Request Forgery": "CSRF",
};
const ICON = {
  gh: '<svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27s1.36.09 2 .27c1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.01 8.01 0 0 0 16 8c0-4.42-3.58-8-8-8Z"/></svg>',
  ext: '<svg class="ext" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M5 11 11 5M6 5h5v5"/></svg>',
  code: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m5.5 4.5-3.5 3.5 3.5 3.5M10.5 4.5 14 8l-3.5 3.5"/></svg>',
  file: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 1.75h5.5L12.5 4.75v9.5h-8.5z"/><path d="M9.25 1.75v3.25h3.25"/></svg>',
  go: '<svg viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M4.5 2.5 8 6l-3.5 3.5"/></svg>',
};

/* ---------- helpers ---------- */
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const esc = (v) => String(v ?? "").replace(/[&<>"']/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[ch]);
const store = {
  get(k) { try { return localStorage.getItem(k); } catch { return null; } },
  set(k, v) { try { localStorage.setItem(k, v); } catch { /* storage unavailable */ } },
};
const SAFE = {
  id: /^(CVE-\d{4}-\d{4,}|BH-\d{4}-\d{3,})$/,
  tid: /^BH-\d{4}-\d{3,}$/,
  repo: /^[A-Za-z0-9-]+\/[A-Za-z0-9._-]+$/,
  ref: /^[A-Za-z0-9._/-]+$/,
  path: /^(?!.*\.\.)[A-Za-z0-9._/-]+$/,
};
const nf = new Intl.NumberFormat("en-GB");
const num = (v) => nf.format(v);
const encPath = (p) => p.split("/").map(encodeURIComponent).join("/");
const httpsUrl = (u) => { try { const x = new URL(u); return x.protocol === "https:" ? x.href : null; } catch { return null; } };
const dateFmt = new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
const fmtDate = (d) => { const t = Date.parse(d); return Number.isNaN(t) ? esc(d) : dateFmt.format(t); };
const plural = (n, word) => `${num(n)} ${word}${n === 1 ? "" : "s"}`;
const debounce = (fn, ms) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };
const isTyping = (el) => el && (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName));
const slugify = (s) => s.toLowerCase().trim().replace(/[^\p{L}\p{N}\s-]/gu, "").replace(/\s+/g, "-");
const idle = () => new Promise((r) => (window.requestIdleCallback ? requestIdleCallback(() => r(), { timeout: 300 }) : setTimeout(r, 16)));
const dayStart = (t) => { const d = new Date(t); d.setHours(0, 0, 0, 0); return d.getTime(); };
const dayKey = (t) => { const d = new Date(t); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; };

function niceTicks(max, count = 3, whole = true) {
  if (max <= 0) return [0, 1];
  const raw = max / count;
  const p = 10 ** Math.floor(Math.log10(raw));
  const nice = [1, 2, 5, 10].map((m) => m * p).find((s) => s >= raw);
  const step = whole ? Math.max(1, nice) : nice; // counts never get fractional ticks
  const top = Math.ceil(max / step) * step;
  const out = [];
  for (let v = 0; v <= top + 1e-9; v += step) out.push(+v.toFixed(6));
  return out;
}

/* ---------- disclosure clock maths (mirrors scripts/bh.mjs in the vault) ---------- */
const dayOf = (reportedMs, d) => (d ? Math.round((Date.parse(String(d).slice(0, 10)) - Date.parse(new Date(reportedMs).toISOString().slice(0, 10))) / DAY) : null);
function lifecycle(raw) {
  const reported = Date.parse(raw?.reported);
  if (Number.isNaN(reported)) return null;
  const windowDays = Number.isInteger(raw.windowDays) && raw.windowDays > 0 ? raw.windowDays : WINDOW_DAYS;
  const extensions = Array.isArray(raw.extensions) ? raw.extensions.filter((e) => Number.isInteger(e?.days) && e.days > 0) : [];
  const ext = extensions.reduce((s, e) => s + e.days, 0);
  const total = windowDays + ext;
  const deadline = reported + total * DAY;
  const releaseAt = Date.parse(raw.releaseAt) || Date.parse(raw.releasedAt) || deadline;
  const fixedDay = raw.fixed && !Number.isNaN(Date.parse(raw.fixed)) ? dayOf(reported, raw.fixed) : null;
  const ackDay = raw.acknowledged && !Number.isNaN(Date.parse(raw.acknowledged)) ? dayOf(reported, raw.acknowledged) : null;
  return { reported, windowDays, extensions, ext, total, deadline, releaseAt, releaseDay: Math.round((releaseAt - reported) / DAY), fixedDay, ackDay, fixed: raw.fixed || null, acknowledged: raw.acknowledged || null };
}
/** Green with ~90 days left, amber around 45, red at 1 day. Always paired with the number itself. */
function clockColor(ms) {
  const t = Math.min(1, Math.max(0, (ms / DAY - 1) / 89));
  return t >= 0.5
    ? `color-mix(in oklch, var(--ok) ${Math.round((t - 0.5) * 200)}%, var(--warn))`
    : `color-mix(in oklch, var(--warn) ${Math.round(t * 200)}%, var(--bad))`;
}
const pad2 = (n) => String(n).padStart(2, "0");
function leftParts(ms) {
  const s = Math.max(0, Math.floor(ms / 1000));
  const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
  return d > 0 ? [[d, "d"], [h, "h"], [m, "m"]] : [[h, "h"], [m, "m"], [sec, "s"]];
}
const countdownHTML = (ms) => leftParts(ms).map(([v, u]) => `<b>${pad2(v)}</b><i>${u}</i>`).join("");
const shortLeft = (ms) => { const [[a, u1], [b, u2]] = leftParts(ms); return `${a}${u1} ${pad2(b)}${u2}`; };
const whenFmt = new Intl.DateTimeFormat("en-GB", { weekday: "short", day: "numeric", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", timeZoneName: "short" });
const shortWhen = new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" });
const dayFmt = new Intl.DateTimeFormat("en-GB", { weekday: "short", day: "numeric", month: "short" });
const monthFmt = new Intl.DateTimeFormat("en-GB", { month: "short", year: "numeric" });
const tickFmt = new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "short" });
const hashOf = (s) => [...s].reduce((a, ch) => (a * 31 + ch.charCodeAt(0)) >>> 0, 7);
function relTime(t, now = Date.now()) {
  const s = Math.max(0, (now - t) / 1000);
  if (s < 90) return "just now";
  if (s < 3600) return `${Math.round(s / 60)} min ago`;
  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
  const d = Math.round(s / 86400);
  return d === 1 ? "yesterday" : `${d} days ago`;
}

/* ---------- loading ---------- */
async function fetchJSON(path) {
  const res = await fetch(SITE.data + path, { cache: "no-cache" });
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  return res.json();
}
let STATS = null;

async function init() {
  wireStatic();
  const embargoP = fetchJSON("embargo.json").catch(() => null);
  try { STATS = await fetchJSON("stats.json"); } catch (err) { showDataError(err); }
  const emb = await embargoP;
  if (emb) loadEmbargo(emb);
  if (!STATS && !EMB.length) return;
  renderLatest();
  renderClock();
  if (STATS?.released?.total) {
    renderStats();
    renderResponse();
    renderRepos();
  } else {
    $("#statistics").hidden = true;
    $("#stats-rule").hidden = true;
  }
  startTicker();
  initIndex();
  route();
  // Sections above may have grown after data loaded: honour a section link such as #clock once more.
  const target = decodeURIComponent(location.hash.slice(1));
  if (target && !/^(cve|bh)-\d{4}-\d+$/i.test(target)) document.getElementById(target)?.scrollIntoView();
}

function showDataError(err) {
  $("#cards").innerHTML = `<div class="data-error"><b>The disclosure data couldn't be loaded</b> (${esc(err.message)}). The files under <code>data/</code> are generated by the vault's publish step. If you opened <code>index.html</code> straight from disk, serve the folder instead, for example with <code>python3 -m http.server</code>.</div>`;
  $("#res-count").textContent = "";
}

/* ---------- static wiring (links from config, keyboard hint) ---------- */
function wireStatic() {
  const site = `https://github.com/${SITE.repo}`;
  $("#gh-site").href = site;
  $("#foot-repo").href = site;
  $("#foot-data").href = `${site}/tree/${SITE.branch}/data`;
  $("#security-link").href = `${site}/blob/${SITE.branch}/SECURITY.md`;
  $("#foot-security").href = `${site}/blob/${SITE.branch}/SECURITY.md`;
  $("#gh-owner").href = `https://github.com/${SITE.owner}`;
  $("#year").textContent = new Date().getFullYear();
  if (!/Mac|iPhone|iPad/.test(navigator.userAgent)) $("#kbd-hint").textContent = "Ctrl K";
}

/* ================= findings under embargo ================= */
let EMB = [];
const EMB_BY_SLUG = new Map();

function loadEmbargo(json) {
  const ix = Object.fromEntries((json.fields ?? []).map((k, i) => [k, i]));
  const types = json.types ?? [], cwes = json.cwes ?? [], exts = json.extensions ?? {};
  EMB = (json.rows ?? []).map((r) => {
    const tid = r[ix.trackingId];
    if (!SAFE.tid.test(tid ?? "")) return null;
    const type = types[r[ix.type]] ?? "Undisclosed class";
    const cwe = r[ix.cwe] >= 0 ? cwes[r[ix.cwe]] ?? null : null;
    const cvss = Number(r[ix.cvss]) || 0;
    const reported = r[ix.reported] * 1000, releaseAt = r[ix.releaseAt] * 1000;
    const windowDays = r[ix.windowDays] || WINDOW_DAYS, ext = r[ix.ext] || 0, total = windowDays + ext;
    const flags = r[ix.flags] | 0;
    const ackDay = r[ix.ackDay] ?? null, fixedDay = r[ix.fixedDay] ?? null;
    const reportedDay = Date.parse(new Date(reported).toISOString().slice(0, 10));
    return {
      kind: "embargo", trackingId: tid, slug: tid.toLowerCase(), type, typeShort: CLASS_SHORT[type] || type, cwe, cvss, severity: severityOf(cvss),
      hold: !!(flags & 1), cveAssigned: !!(flags & 2),
      fixedAt: fixedDay != null ? reportedDay + fixedDay * DAY : null,
      life: { reported, windowDays, ext, total, deadline: reported + total * DAY, releaseAt, releaseDay: Math.round((releaseAt - reported) / DAY), ackDay, fixedDay, extensions: exts[tid] ?? [] },
      hay: `${tid} ${type} ${CLASS_SHORT[type] ?? ""} ${cwe ?? ""}`.toLowerCase(),
    };
  }).filter(Boolean).sort((a, b) => a.life.releaseAt - b.life.releaseAt);
  EMB.forEach((e) => EMB_BY_SLUG.set(e.slug, e));
}

function clockState(e, now = Date.now()) {
  const ms = e.life.releaseAt - now;
  if (e.hold) return "paused";
  if (ms <= 0) return "due";
  if (ms < DAY) return "final";
  if (ms < 7 * DAY) return "soon";
  return "running";
}
const elapsedDays = (reported, total, now = Date.now()) => Math.min(total, Math.max(0, Math.floor((now - reported) / DAY)));

/* board state: tab = sort order, the rest are filters */
const CB = { tab: "next", sev: "all", cls: "all", status: "all", day: null, q: "", view: store.get("bh:cview") === "list" ? "list" : "grid", shown: BOARD_PAGE };
const STATUS = {
  all: ["Any status", () => true],
  awaiting: ["Awaiting vendor", (e) => e.life.ackDay == null && e.life.fixedDay == null],
  ack: ["Acknowledged, not fixed", (e) => e.life.ackDay != null && e.life.fixedDay == null],
  fixed: ["Fixed by vendor", (e) => e.life.fixedDay != null],
  extended: ["Extended", (e) => e.life.ext > 0],
  paused: ["Release paused", (e) => e.hold],
  cve: ["CVE assigned", (e) => e.cveAssigned],
};

function renderClock() {
  if (!EMB.length) {
    $("#clock").hidden = true;
    $("#clock-rule").hidden = true;
    $("#nav-clock").hidden = true;
    return;
  }
  $("#clock").hidden = false;
  const now = Date.now();
  $("#clock-kicker").textContent = `${plural(EMB.length, "finding")} under embargo · ${WINDOW_DAYS}-day clock`;
  renderClockStats(now);
  renderForecast(now);
  buildBoardControls();
  renderBoard();
  renderFeed(now);
}

function renderClockStats(now) {
  const active = EMB.filter((e) => !e.hold);
  const next = active[0];
  const in24 = active.filter((e) => e.life.releaseAt - now <= DAY).length;
  const in7 = active.filter((e) => e.life.releaseAt - now <= 7 * DAY).length;
  const newToday = EMB.filter((e) => now - e.life.reported <= DAY).length;
  const fixedN = EMB.filter((e) => e.fixedAt != null).length;
  const spark = new Array(14).fill(0);
  const d0 = dayStart(now) - 13 * DAY;
  for (const e of EMB) { const i = Math.round((dayStart(e.life.reported) - d0) / DAY); if (i >= 0 && i < 14) spark[i]++; }
  const sparkMax = Math.max(1, ...spark);
  $("#clock-stats").innerHTML = `
    <div class="cstat"><span class="cl">Under embargo</span><b class="cv num">${num(EMB.length)}</b><span class="cs">vendors notified, details withheld</span></div>
    <div class="cstat"><span class="cl">Reported in the last 24 h</span><b class="cv num">${num(newToday)}</b><span class="spark" role="img" aria-label="Findings reported per day, last 14 days: ${spark.join(", ")}">${spark.map((v, i) => `<i data-tip-title="${esc(dayFmt.format(d0 + i * DAY))}" data-tip-body="${plural(v, "finding")} reported"></i>`).join("")}</span></div>
    <div class="cstat"><span class="cl">Releasing within 24 h</span><b class="cv num">${num(in24)}</b><span class="cs">${num(in7)} within 7 days</span></div>
    <div class="cstat"><span class="cl">Patched under embargo</span><b class="cv num">${num(fixedN)}<small>/ ${num(EMB.length)}</small></b><span class="cs">${Math.round((fixedN / EMB.length) * 100)}% fixed before release</span></div>
    ${next ? `<a class="cstat tone" href="#${next.slug}" data-until="${next.life.releaseAt}" data-kind="tone"><span class="cl">Next full disclosure</span><b class="cv mono" data-until="${next.life.releaseAt}" data-mode="short">${shortLeft(next.life.releaseAt - now)}</b><span class="cs">${esc(next.trackingId)} · ${esc(shortWhen.format(next.life.releaseAt))}</span></a>`
      : '<div class="cstat"><span class="cl">Next full disclosure</span><b class="cv">–</b><span class="cs">all releases paused</span></div>'}`;
  $$("#clock-stats .spark i").forEach((el, i) => { el.style.height = `${Math.max(8, (spark[i] / sparkMax) * 100)}%`; if (!spark[i]) el.classList.add("zero"); });
}

/* full-disclosure forecast: one column per day, click to filter the board */
function renderForecast(now) {
  const root = $("#forecast");
  const start = dayStart(now);
  const active = EMB.filter((e) => !e.hold);
  const lastRel = active.reduce((m, e) => Math.max(m, e.life.releaseAt), start + WINDOW_DAYS * DAY);
  const days = Math.min(200, Math.round((dayStart(lastRel) - start) / DAY) + 1);
  const bins = Array.from({ length: days }, (_, i) => ({ n: 0, t: start + i * DAY, sev: { Critical: 0, High: 0, Medium: 0, Low: 0 } }));
  for (const e of active) {
    const i = Math.max(0, Math.min(days - 1, Math.round((dayStart(e.life.releaseAt) - start) / DAY)));
    bins[i].n++;
    bins[i].sev[e.severity]++;
  }
  const max = Math.max(1, ...bins.map((b) => b.n));
  const ticks = niceTicks(max, 2);
  const top = ticks[ticks.length - 1];
  const peak = bins.reduce((m, b) => (b.n > m.n ? b : m), bins[0]);
  root.innerHTML = `<div class="fc-y">${ticks.map((t) => `<span data-v="${t}">${num(t)}</span>`).join("")}</div>
    <div class="fc-main"><div class="fc-plot">${ticks.slice(1).map((t) => `<i class="fc-grid" data-v="${t}"></i>`).join("")}<div class="fc-cols"></div></div><div class="fc-x"></div></div>`;
  $$(".fc-y span, .fc-grid", root).forEach((el) => (el.style.bottom = `${(+el.dataset.v / top) * 100}%`));
  const cols = $(".fc-cols", root);
  cols.style.gridTemplateColumns = `repeat(${days}, minmax(0, 1fr))`;
  const key = (t) => dayKey(t);
  cols.innerHTML = bins.map((b, i) => `<button type="button" class="fc-col${CB.day === key(b.t) ? " on" : ""}" data-day="${key(b.t)}" ${b.n ? "" : "disabled"}
      aria-label="${esc(`${dayFmt.format(b.t)}: ${plural(b.n, "release")}`)}" data-tip-title="${esc(`${i === 0 ? "Today" : dayFmt.format(b.t)} · ${plural(b.n, "release")}`)}"
      data-tip-body="${esc(SEVERITIES.filter((s) => b.sev[s]).map((s) => `${s} ${num(b.sev[s])}`).join(" · ") || "none")}"><span class="fc-bar"></span></button>`).join("");
  $$(".fc-col", cols).forEach((el, i) => {
    const bar = $(".fc-bar", el);
    bar.style.height = bins[i].n ? `max(3px, ${(bins[i].n / top) * 100}%)` : "0";
    bar.style.background = clockColor(bins[i].t + DAY / 2 - now);
  });
  const x = $(".fc-x", root);
  const label = (i, text, cls = "") => { const s = document.createElement("span"); s.className = cls; s.style.left = `${((i + 0.5) / days) * 100}%`; s.textContent = text; x.append(s); };
  label(0, "Today", "today");
  for (let i = 1; i < days; i++) {
    const d = new Date(bins[i].t);
    const px = ((i + 0.5) / days) * (x.clientWidth || 600);
    if (d.getDate() === 1 && px > 72 && px < (x.clientWidth || 600) - 24) label(i, tickFmt.format(d));
  }
  const total = active.length;
  $("#forecast-sub").textContent = `Next ${days} days · ${plural(total, "release")} · busiest ${peak.n ? `${dayFmt.format(peak.t)} (${num(peak.n)})` : "–"}`;
  // monthly totals
  const months = new Map();
  for (const e of active) { const k = monthFmt.format(e.life.releaseAt); months.set(k, (months.get(k) || 0) + 1); }
  const paused = EMB.length - active.length;
  $("#release-months").innerHTML = [...months].map(([k, v]) => `<span class="month"><b class="num">${num(v)}</b>${esc(k)}</span>`).join("")
    + (paused ? `<span class="month"><b class="num">${num(paused)}</b>paused</span>` : "");
}

function buildBoardControls() {
  const classes = [...new Set(EMB.map((e) => e.type))].sort();
  $("#c-class").innerHTML = `<option value="all">All classes</option>${classes.map((t) => `<option value="${esc(t)}">${esc(t)}</option>`).join("")}`;
  $("#c-sev").innerHTML = `<option value="all">All severities</option>${SEVERITIES.map((s) => `<option value="${s}">${s} (${num(EMB.filter((e) => e.severity === s).length)})</option>`).join("")}`;
  $("#c-status").innerHTML = Object.entries(STATUS).map(([k, [label, fn]]) => `<option value="${k}">${label}${k === "all" ? "" : ` (${num(EMB.filter(fn).length)})`}</option>`).join("");
  $("#c-view-grid").setAttribute("aria-pressed", String(CB.view === "grid"));
  $("#c-view-list").setAttribute("aria-pressed", String(CB.view === "list"));
}

function boardList() {
  const terms = CB.q.toLowerCase().split(/\s+/).filter(Boolean);
  const statusFn = (STATUS[CB.status] ?? STATUS.all)[1];
  let list = EMB.filter((e) =>
    (CB.sev === "all" || e.severity === CB.sev) &&
    (CB.cls === "all" || e.type === CB.cls) &&
    statusFn(e) &&
    (!CB.day || dayKey(e.life.releaseAt) === CB.day) &&
    (!terms.length || terms.every((t) => e.hay.includes(t))));
  if (CB.tab === "newest") list.sort((a, b) => b.life.reported - a.life.reported);
  else if (CB.tab === "fixed") list = list.filter((e) => e.fixedAt != null).sort((a, b) => b.fixedAt - a.fixedAt || a.life.releaseAt - b.life.releaseAt);
  else if (CB.tab === "cvss") list.sort((a, b) => b.cvss - a.cvss || a.life.releaseAt - b.life.releaseAt);
  else list.sort((a, b) => a.hold - b.hold || a.life.releaseAt - b.life.releaseAt);
  return list;
}
const boardFiltered = () => CB.sev !== "all" || CB.cls !== "all" || CB.status !== "all" || CB.day || CB.q.trim();

function renderBoard() {
  const list = boardList();
  const shown = list.slice(0, CB.shown);
  const grid = $("#embargo-grid");
  grid.classList.toggle("list", CB.view === "list");
  grid.innerHTML = shown.length
    ? shown.map(CB.view === "list" ? embargoRow : embargoCard).join("")
    : `<div class="empty"><p>${CB.tab === "fixed" && !boardFiltered() ? "No vendor has shipped a fix for a finding under embargo yet." : "No findings under embargo match these filters."}</p>${boardFiltered() ? '<button type="button" class="linkbtn" data-cclear>Clear filters</button>' : ""}</div>`;
  $$(".ecard", grid).forEach((card) => {
    const h = hashOf(card.dataset.eid);
    const [a, b] = $$(".redact span", card);
    a.style.width = `${54 + (h % 32)}%`;
    b.style.width = `${30 + ((h >> 5) % 28)}%`;
  });
  $("#board-count").innerHTML = `Showing <b>${num(shown.length)}</b> of <b>${num(list.length)}</b>${list.length !== EMB.length ? ` · ${num(EMB.length)} under embargo` : " under embargo"}`;
  const chip = $("#board-day");
  chip.hidden = !CB.day;
  if (CB.day) $("span", chip).textContent = `Releasing ${dayFmt.format(new Date(`${CB.day}T12:00:00`))}`;
  $("#board-clear").hidden = !boardFiltered();
  const more = $("#board-more");
  more.hidden = list.length <= CB.shown;
  more.textContent = `Show ${num(Math.min(BOARD_PAGE, list.length - CB.shown))} more`;
  $$("#forecast .fc-col").forEach((el) => el.classList.toggle("on", el.dataset.day === CB.day));
  tick();
}

function statusTag(e) {
  const l = e.life;
  if (e.hold) return '<span class="tag">Paused</span>';
  if (l.fixedDay != null) return `<span class="tag t-ok"><i></i>Fixed d${l.fixedDay}</span>`;
  if (l.ackDay != null) return '<span class="tag">Not fixed yet</span>';
  return '<span class="tag t-warn"><i></i>Awaiting vendor</span>';
}

function embargoCard(e) {
  const l = e.life;
  return `<a class="ecard s-${e.severity}" href="#${e.slug}" data-eid="${e.slug}" data-until="${l.releaseAt}" data-kind="tone" aria-label="${esc(`${e.trackingId}: ${e.type}, ${e.severity} ${e.cvss.toFixed(1)}. Vendor and product withheld until ${whenFmt.format(l.releaseAt)}.`)}">
    <div class="e-top"><span class="e-id">${esc(e.trackingId)}</span><span class="sev"><i></i>${esc(e.severity)}</span><span class="score num">${e.cvss.toFixed(1)}<small>CVSS</small></span></div>
    <div class="redact" aria-hidden="true"><span></span><span></span></div>
    <div class="e-class">${esc(e.type)}${e.cwe ? ` <span>· ${esc(e.cwe)}</span>` : ""}</div>
    <div class="e-clock">
      <div class="cd" data-until="${l.releaseAt}" data-mode="full">${countdownHTML(l.releaseAt - Date.now())}</div>
      <div class="cd-sub" data-until="${l.releaseAt}" data-mode="state" data-eid="${e.slug}">until vendor and product are disclosed</div>
    </div>
    <div class="wbar" aria-hidden="true" data-reported="${l.reported}" data-total="${l.total}" data-window="${l.windowDays}" data-fix="${l.fixedDay ?? ""}">
      <span class="w-el"></span><span class="w-rem"></span>${l.ext ? '<span class="w-ext"></span>' : ""}${l.fixedDay != null ? '<span class="w-fix"></span>' : ""}
    </div>
    <div class="e-foot">
      <span class="e-day" data-reported="${l.reported}" data-total="${l.total}">Day ${elapsedDays(l.reported, l.total)} of ${l.total}</span>
      ${statusTag(e)}${l.ext ? `<span class="tag">+${l.ext}d</span>` : ""}${e.cveAssigned ? '<span class="tag">CVE</span>' : ""}
    </div>
  </a>`;
}

function embargoRow(e) {
  const l = e.life;
  return `<a class="erow s-${e.severity}" href="#${e.slug}" data-eid="${e.slug}" data-until="${l.releaseAt}" data-kind="tone" aria-label="${esc(`${e.trackingId}: ${e.type}, ${e.severity} ${e.cvss.toFixed(1)}, releases ${whenFmt.format(l.releaseAt)}`)}">
    <span class="e-id">${esc(e.trackingId)}</span>
    <span class="r-class">${esc(e.typeShort)}${e.cwe ? ` <small>${esc(e.cwe)}</small>` : ""}</span>
    <span class="sev"><i></i>${esc(e.severity)} <b class="num">${e.cvss.toFixed(1)}</b></span>
    <span class="r-left mono" data-until="${l.releaseAt}" data-mode="short">${shortLeft(l.releaseAt - Date.now())}</span>
    <span class="r-when">${esc(shortWhen.format(l.releaseAt))}</span>
    <span class="r-status">${statusTag(e)}</span>
  </a>`;
}

/* latest activity: newly reported, newly fixed, newly released */
function renderFeed(now) {
  const events = [];
  [...EMB].sort((a, b) => b.life.reported - a.life.reported).slice(0, 10).forEach((e) => events.push({ t: e.life.reported, kind: "new", e }));
  EMB.filter((e) => e.fixedAt != null).sort((a, b) => b.fixedAt - a.fixedAt).slice(0, 10).forEach((e) => events.push({ t: e.fixedAt, kind: "fixed", e }));
  (STATS?.released?.latest ?? []).forEach((r) => events.push({ t: Date.parse(r.releasedAt || r.date), kind: "released", r }));
  const list = events.filter((ev) => ev.t <= now + DAY).sort((a, b) => b.t - a.t).slice(0, 9);
  $("#feed-list").innerHTML = list.map((ev) => {
    if (ev.kind === "released") {
      const r = ev.r;
      return `<li class="fe-released"><i aria-hidden="true"></i><a href="#${esc(String(r.id).toLowerCase())}"><b>${esc(r.id)}</b> disclosed · ${esc(r.vendor)} ${esc(r.product)}</a><time data-rel="${ev.t}">${relTime(ev.t, now)}</time></li>`;
    }
    const e = ev.e;
    return ev.kind === "fixed"
      ? `<li class="fe-fixed"><i aria-hidden="true"></i><a href="#${e.slug}"><b>${esc(e.trackingId)}</b> fixed by the vendor on day ${e.life.fixedDay}</a><time data-rel="${ev.t}">${relTime(ev.t, now)}</time></li>`
      : `<li class="fe-new s-${e.severity}"><i aria-hidden="true"></i><a href="#${e.slug}"><b>${esc(e.trackingId)}</b> reported · ${esc(e.typeShort)} ${e.cvss.toFixed(1)}</a><time data-rel="${ev.t}">${relTime(ev.t, now)}</time></li>`;
  }).join("") || '<li class="fe-empty">No activity yet.</li>';
}

function layoutBar(bar, now) {
  const reported = +bar.dataset.reported, total = +bar.dataset.total, win = +bar.dataset.window;
  const el = Math.min(1, Math.max(0, (now - reported) / (total * DAY)));
  $(".w-el", bar).style.width = `${el * 100}%`;
  const rem = $(".w-rem", bar);
  rem.style.left = `${el * 100}%`;
  rem.style.width = `${(1 - el) * 100}%`;
  const ext = $(".w-ext", bar);
  if (ext) ext.style.left = `${(win / total) * 100}%`;
  const fix = $(".w-fix", bar);
  if (fix) fix.style.left = `${Math.min(100, (+bar.dataset.fix / total) * 100)}%`;
}

function wireBoard() {
  $("#clock-tabs").addEventListener("click", (e) => {
    const b = e.target.closest("button[data-tab]");
    if (!b) return;
    CB.tab = b.dataset.tab;
    CB.shown = BOARD_PAGE;
    $$("#clock-tabs button").forEach((x) => x.setAttribute("aria-selected", String(x === b)));
    renderBoard();
  });
  $("#cq").addEventListener("input", debounce((e) => { CB.q = e.target.value; CB.shown = BOARD_PAGE; renderBoard(); }, 120));
  for (const [id, key] of [["#c-sev", "sev"], ["#c-class", "cls"], ["#c-status", "status"]]) {
    $(id).addEventListener("change", (e) => { CB[key] = e.target.value; CB.shown = BOARD_PAGE; renderBoard(); });
  }
  const setView = (v) => { CB.view = v; store.set("bh:cview", v); $("#c-view-grid").setAttribute("aria-pressed", String(v === "grid")); $("#c-view-list").setAttribute("aria-pressed", String(v === "list")); renderBoard(); };
  $("#c-view-grid").addEventListener("click", () => setView("grid"));
  $("#c-view-list").addEventListener("click", () => setView("list"));
  $("#board-more").addEventListener("click", () => { CB.shown += BOARD_PAGE; renderBoard(); });
  const clear = () => {
    Object.assign(CB, { sev: "all", cls: "all", status: "all", day: null, q: "", shown: BOARD_PAGE });
    $("#cq").value = ""; $("#c-sev").value = "all"; $("#c-class").value = "all"; $("#c-status").value = "all";
    renderBoard();
  };
  $("#board-clear").addEventListener("click", clear);
  $("#board-day button").addEventListener("click", () => { CB.day = null; CB.shown = BOARD_PAGE; renderBoard(); });
  $("#embargo-grid").addEventListener("click", (e) => { if (e.target.closest("[data-cclear]")) clear(); });
  $("#forecast").addEventListener("click", (e) => {
    const b = e.target.closest("button[data-day]");
    if (!b) return;
    CB.day = CB.day === b.dataset.day ? null : b.dataset.day;
    CB.tab = "next";
    CB.shown = BOARD_PAGE;
    $$("#clock-tabs button").forEach((x) => x.setAttribute("aria-selected", String(x.dataset.tab === "next")));
    renderBoard();
    if (CB.day) $("#board").scrollIntoView({ behavior: "smooth", block: "start" });
  });
}

/* ================= released disclosures ================= */
let IDX = [];
const BY_SLUG = new Map();
const IDX_CLASSES = new Set();
const SHARDS = { years: [], loaded: new Set(), pending: new Map(), done: null, complete: false };
const IST = { q: "", sev: "all", year: "all", cls: "all", poc: false, sort: "date-desc", view: store.get("bh:view") === "list" ? "list" : "grid", shown: INDEX_PAGE };

function decodeIndex(json) {
  const ix = Object.fromEntries((json.fields ?? []).map((k, i) => [k, i]));
  const types = json.types ?? [];
  return (json.rows ?? []).map((r) => {
    const id = String(r[ix.id] ?? "").toUpperCase();
    if (!SAFE.id.test(id)) return null;
    const type = types[r[ix.type]] ?? "Other";
    const cvss = Number(r[ix.cvss]) || 0;
    const repo = SAFE.repo.test(r[ix.repo] ?? "") ? r[ix.repo] : null;
    IDX_CLASSES.add(type);
    return {
      kind: "cve", id, slug: id.toLowerCase(), trackingId: SAFE.tid.test(r[ix.trackingId] ?? "") ? r[ix.trackingId] : null,
      title: r[ix.title] ?? "", vendor: r[ix.vendor] ?? "", product: r[ix.product] ?? "", type, typeShort: CLASS_SHORT[type] || type,
      cwe: r[ix.cwe] ?? null, date: r[ix.date] ?? "", year: String(r[ix.date] ?? "").slice(0, 4), cvss, severity: severityOf(cvss),
      fixedDay: r[ix.fixedDay] ?? null, releaseDay: r[ix.releaseDay] ?? null, repo, poc: !!r[ix.poc], full: null,
    };
  }).filter(Boolean);
}
const hayOf = (c) => (c.hay ??= [c.id, c.trackingId, c.title, c.vendor, c.product, c.type, c.typeShort, c.cwe, c.repo].join(" ").toLowerCase());

function loadShard(y) {
  if (SHARDS.loaded.has(y)) return Promise.resolve();
  if (SHARDS.pending.has(y)) return SHARDS.pending.get(y);
  const p = fetchJSON(`index/${y}.json`).then((json) => {
    const rows = decodeIndex(json);
    const inOrder = !IDX.length || IDX[IDX.length - 1].date >= (rows[0]?.date ?? "");
    for (const c of rows) {
      IDX.push(c);
      BY_SLUG.set(c.slug, c);
      if (c.trackingId) BY_SLUG.set(c.trackingId.toLowerCase(), c);
    }
    if (!inOrder) IDX.sort((a, b) => b.date.localeCompare(a.date) || a.id.localeCompare(b.id));
    SHARDS.loaded.add(y);
  }).catch((err) => { console.warn(err); }).finally(() => SHARDS.pending.delete(y));
  SHARDS.pending.set(y, p);
  return p;
}

async function initIndex() {
  SHARDS.years = STATS?.index ?? [];
  buildIndexFilters();
  if (!SHARDS.years.length) { SHARDS.complete = true; renderCards(); return; }
  SHARDS.first = loadShard(SHARDS.years[0]);
  await SHARDS.first;
  renderCards();
  // older years load in the background, newest first
  SHARDS.done = (async () => {
    for (const y of SHARDS.years.slice(1)) {
      await idle();
      await loadShard(y);
      refreshIndex();
    }
    SHARDS.complete = true;
    refreshIndex();
  })();
}
const refreshIndex = debounce(() => { refreshClassOptions(); renderCards(); }, 150);

function buildIndexFilters() {
  const total = STATS?.released?.total ?? 0;
  const sev = STATS?.released?.severity ?? {};
  const seg = $("#seg-sev");
  seg.innerHTML = [["all", "All", total], ...SEVERITIES.map((s) => [s, s, sev[s] ?? 0])].map(([v, label, k]) =>
    `<button type="button" data-sev="${v}" aria-pressed="${v === IST.sev}" class="s-${v}">${v === "all" ? "" : '<i class="fill-sev"></i>'}${label}<span class="n">${num(k)}</span></button>`).join("");
  const years = STATS?.released?.years ?? {};
  $("#f-year").innerHTML = `<option value="all">All years</option>${SHARDS.years.map((y) => `<option value="${esc(y)}">${esc(y)} (${num(years[y] ?? 0)})</option>`).join("")}`;
  refreshClassOptions();
  syncViewButtons();
}
function refreshClassOptions() {
  const sel = $("#f-class");
  const keep = IST.cls;
  const classes = [...new Set([...(STATS?.released?.classes ?? []).map(([t]) => t), ...IDX_CLASSES])].sort();
  sel.innerHTML = `<option value="all">All classes</option>${classes.map((t) => `<option value="${esc(t)}">${esc(t)}</option>`).join("")}`;
  sel.value = classes.includes(keep) ? keep : "all";
}

function wireIndex() {
  $("#seg-sev").addEventListener("click", (e) => {
    const b = e.target.closest("button[data-sev]");
    if (!b) return;
    IST.sev = b.dataset.sev;
    IST.shown = INDEX_PAGE;
    $$("#seg-sev button").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
    renderCards();
  });
  $("#q").addEventListener("input", debounce((e) => { IST.q = e.target.value; IST.shown = INDEX_PAGE; renderCards(); }, 150));
  $("#f-year").addEventListener("change", async (e) => {
    IST.year = e.target.value;
    IST.shown = INDEX_PAGE;
    if (IST.year !== "all" && !SHARDS.loaded.has(IST.year)) { renderCards(); await loadShard(IST.year); }
    renderCards();
  });
  $("#f-class").addEventListener("change", (e) => { IST.cls = e.target.value; IST.shown = INDEX_PAGE; renderCards(); });
  $("#f-poc").addEventListener("change", (e) => { IST.poc = e.target.checked; IST.shown = INDEX_PAGE; renderCards(); });
  $("#f-sort").addEventListener("change", (e) => { IST.sort = e.target.value; IST.shown = INDEX_PAGE; renderCards(); });
  $("#v-grid").addEventListener("click", () => setView("grid"));
  $("#v-list").addEventListener("click", () => setView("list"));
  $("#clear-filters").addEventListener("click", clearFilters);
  $("#cards").addEventListener("click", (e) => { if (e.target.closest("[data-clear]")) clearFilters(); });
  $("#index-more").addEventListener("click", () => { IST.shown += INDEX_PAGE; renderCards(); });
}
function setView(v) { IST.view = v; store.set("bh:view", v); syncViewButtons(); renderCards(); }
function syncViewButtons() {
  $("#v-grid").setAttribute("aria-pressed", String(IST.view === "grid"));
  $("#v-list").setAttribute("aria-pressed", String(IST.view === "list"));
}
const isFiltered = () => IST.q.trim() || IST.sev !== "all" || IST.year !== "all" || IST.cls !== "all" || IST.poc;
function clearFilters() {
  Object.assign(IST, { q: "", sev: "all", year: "all", cls: "all", poc: false, shown: INDEX_PAGE });
  $("#q").value = ""; $("#f-year").value = "all"; $("#f-class").value = "all"; $("#f-poc").checked = false;
  $$("#seg-sev button").forEach((x) => x.setAttribute("aria-pressed", String(x.dataset.sev === "all")));
  renderCards();
}

function filteredIndex() {
  const terms = IST.q.toLowerCase().split(/\s+/).filter(Boolean);
  const list = IDX.filter((c) =>
    (IST.sev === "all" || c.severity === IST.sev) &&
    (IST.year === "all" || c.year === IST.year) &&
    (IST.cls === "all" || c.type === IST.cls) &&
    (!IST.poc || c.poc) &&
    (!terms.length || terms.every((t) => hayOf(c).includes(t))));
  if (IST.sort === "date-desc") return list; // IDX is kept newest first
  if (IST.sort === "date-asc") return list.reverse();
  const sign = IST.sort === "cvss-asc" ? 1 : -1;
  return list.sort((a, b) => (a.cvss - b.cvss) * sign || b.date.localeCompare(a.date));
}

const label = (c) => esc(`${c.id}: ${c.title}. ${c.severity}, CVSS ${c.cvss.toFixed(1)}. ${c.vendor} ${c.product}`);
function fixTag(c) {
  if (c.releaseDay == null) return "";
  if (c.fixedDay == null) return '<span class="tag t-bad"><i></i>Unpatched</span>';
  if (c.fixedDay > c.releaseDay) return '<span class="tag t-warn"><i></i>Fixed after disclosure</span>';
  return `<span class="tag t-ok"><i></i>Fixed d${c.fixedDay}</span>`;
}
const cardTpl = (c) => `<a class="card s-${c.severity}" href="#${c.slug}" aria-label="${label(c)}">
  <div class="c-top"><span class="sev"><i></i>${esc(c.severity)}</span><span class="score num">${c.cvss.toFixed(1)}<small>CVSS</small></span></div>
  <div class="c-id">${esc(c.id)}</div>
  <h3 class="c-title">${esc(c.title)}</h3>
  <div class="c-meta">${esc(c.vendor)} · ${esc(c.product)}</div>
  <div class="c-foot"><span class="tag">${esc(c.typeShort)}</span>${fixTag(c)}${c.poc ? '<span class="tag">PoC</span>' : ""}${c.repo ? `<span class="c-repo">${ICON.gh}<span>${esc(c.repo)}</span></span>` : ""}</div>
</a>`;
const rowTpl = (c) => `<a class="card s-${c.severity}" href="#${c.slug}" aria-label="${label(c)}">
  <span class="c-id">${esc(c.id)}</span>
  <span class="l-main"><span class="c-title">${esc(c.title)}</span><span class="c-meta">${esc(c.vendor)} · ${esc(c.product)}</span></span>
  <span class="l-class"><span class="tag">${esc(c.typeShort)}</span></span>
  <span class="sev l-sev"><i></i>${esc(c.severity)}</span>
  <span class="score num">${c.cvss.toFixed(1)}</span>
  <span class="l-date">${fmtDate(c.date)}</span>
</a>`;

function renderCards() {
  const el = $("#cards");
  const total = STATS?.released?.total ?? 0;
  const more = $("#index-more");
  if (!total) {
    el.innerHTML = `<div class="empty"><p>No disclosures have been published yet. Findings under embargo are listed in the disclosure clock above.</p></div>`;
    $("#res-count").textContent = "";
    more.hidden = true;
    return;
  }
  const list = filteredIndex();
  const shown = list.slice(0, IST.shown);
  el.classList.toggle("list", IST.view === "list");
  el.innerHTML = shown.length
    ? shown.map(IST.view === "list" ? rowTpl : cardTpl).join("")
    : `<div class="empty"><p>${SHARDS.pending.size ? "Loading…" : "No disclosures match these filters."}</p>${isFiltered() ? '<button type="button" class="linkbtn" data-clear>Clear filters</button>' : ""}</div>`;
  const loading = IDX.length < total && !SHARDS.complete;
  $("#res-count").innerHTML = `Showing <b>${num(shown.length)}</b> of <b>${num(list.length)}</b>${isFiltered() ? " matching" : ""}${loading ? ` · loading older years (${num(IDX.length)} of ${num(total)})` : ` · ${num(total)} disclosures`}`;
  $("#clear-filters").hidden = !isFiltered();
  more.hidden = list.length <= IST.shown;
  more.textContent = `Show ${num(Math.min(INDEX_PAGE, list.length - IST.shown))} more`;
}

/* ---------- hero ---------- */
function renderLatest() {
  const a = $("#latest");
  const next = EMB.find((e) => !e.hold);
  if (next) {
    a.href = "#clock";
    a.setAttribute("aria-label", `${EMB.length} findings under embargo. Next release ${whenFmt.format(next.life.releaseAt)}`);
    a.innerHTML = `<span class="pulse" aria-hidden="true"></span><span class="lid">${num(EMB.length)} under embargo</span><span class="lt">next release in <span class="mono" data-until="${next.life.releaseAt}" data-mode="short">${shortLeft(next.life.releaseAt - Date.now())}</span></span><span class="go">${ICON.go}</span>`;
    return;
  }
  const c = STATS?.released?.latest?.[0];
  if (!c) return;
  a.href = `#${String(c.id).toLowerCase()}`;
  a.setAttribute("aria-label", `Latest disclosure: ${c.id}, ${c.title}`);
  a.innerHTML = `<span class="pulse" aria-hidden="true"></span><span class="lid">${esc(c.id)}</span><span class="lt">${esc(c.product)} · ${esc(c.severity)} ${Number(c.cvss).toFixed(1)}</span><span class="go">${ICON.go}</span>`;
}

/* ---------- statistics (precomputed by the vault) ---------- */
function renderStats() {
  const R = STATS.released;
  const n = R.total;
  const years = Object.keys(R.years).map(Number).sort((a, b) => a - b);
  const minY = years[0], maxY = years[years.length - 1];
  $("#stats-kicker").textContent = `data/stats.json · ${plural(n, "disclosure")} · latest ${R.latest?.[0] ? fmtDate(R.latest[0].date) : "–"}`;
  $("#disc-kicker").textContent = `${plural(n, "disclosure")} · ${minY}–${maxY}`;
  $("#fig-total").textContent = num(n);
  $("#sub-total").textContent = `confirmed vulnerabilities published since ${minY}`;
  renderYears(R.years, minY, maxY);

  const counts = SEVERITIES.map((s) => [s, R.severity[s] ?? 0]).filter(([, k]) => k > 0);
  $("#chart-sev").replaceChildren(...counts.map(([s, k]) => {
    const part = document.createElement("div");
    part.className = `part fill-sev ink-on-c s-${s}`;
    part.style.flexGrow = k;
    part.style.flexBasis = "0";
    part.tabIndex = 0;
    part.dataset.tipTitle = s;
    part.dataset.tipBody = `${plural(k, "CVE")} · ${Math.round((k / n) * 100)}% of total`;
    part.setAttribute("aria-label", `${s}: ${k} of ${n}`);
    const lab = document.createElement("span");
    lab.className = "pl";
    lab.textContent = num(k);
    part.append(lab);
    return part;
  }));
  $("#legend-sev").innerHTML = counts.map(([s]) => `<span class="s-${s}"><i class="fill-sev"></i>${s}</span>`).join("");
  $("#sub-sev").textContent = `${num((R.severity.Critical ?? 0) + (R.severity.High ?? 0))} of ${num(n)} rated High or Critical`;
  fitSegLabels();

  if (R.cvss) {
    $("#fig-cvss").textContent = R.cvss.avg.toFixed(1);
    $("#cvss-mark").style.left = `calc(${(R.cvss.avg / 10) * 100}% - 1px)`;
    const sub = document.createElement("p");
    sub.className = "sub";
    sub.textContent = `range ${R.cvss.min.toFixed(1)}–${R.cvss.max.toFixed(1)}`;
    $(".t-cvss").append(sub);
  }
  const pct = Math.round((R.poc / n) * 100);
  $("#fig-poc").innerHTML = `${num(R.poc)}<small>/ ${num(n)}</small>`;
  $("#meter-poc-fill").style.width = `${pct}%`;
  $("#meter-poc").setAttribute("aria-label", `${R.poc} of ${n} disclosures have a public proof of concept`);
  $("#sub-poc").textContent = `${pct}% ship with a public PoC`;

  const cls = R.classes.map(([t, k]) => [CLASS_SHORT[t] || t, k]).slice(0, 6);
  const maxC = cls[0]?.[1] ?? 1;
  $("#chart-cls").replaceChildren(...cls.map(([lab, k]) => {
    const row = document.createElement("div");
    row.className = "row";
    row.tabIndex = 0;
    row.dataset.tipTitle = lab;
    row.dataset.tipBody = `${plural(k, "CVE")} · ${Math.round((k / n) * 100)}% of total`;
    row.innerHTML = `<span class="lab">${esc(lab)}</span><span class="track"><span class="fill"></span><span class="val">${num(k)}</span></span>`;
    $(".fill", row).style.width = `calc((100% - 44px) * ${k / maxC})`;
    return row;
  }));
  $("#fig-vend").textContent = num(R.vendors);
  $("#list-vend").innerHTML = R.vendorsTop.map(([v, k]) => `<div><span>${esc(v)}</span><b>${num(k)}</b></div>`).join("");
  $("#fig-repo").textContent = num(R.repos);
  $("#sub-repo").textContent = `${num(R.withRepo)} of ${num(n)} disclosures link a writeup on GitHub`;
}

function renderYears(counts, minY, maxY) {
  const years = [];
  for (let y = minY; y <= maxY; y++) years.push([String(y), counts[y] ?? 0]);
  const max = Math.max(...years.map(([, k]) => k));
  const ticks = niceTicks(max, 3);
  const top = ticks[ticks.length - 1];
  const lastIdx = years.length - 1;
  const maxIdx = years.findIndex(([, k]) => k === max);
  const root = $("#chart-years");
  root.innerHTML = '<div class="yax"></div><div class="plot"><div class="area"></div><div class="xax"></div></div>';
  const yax = $(".yax", root), area = $(".area", root), xax = $(".xax", root);
  ticks.forEach((t) => {
    const s = document.createElement("span");
    s.textContent = num(t);
    s.style.bottom = `${(t / top) * 100}%`;
    yax.append(s);
    if (t > 0) {
      const g = document.createElement("div");
      g.className = "grid";
      g.style.bottom = `${(t / top) * 100}%`;
      area.append(g);
    }
  });
  years.forEach(([y, k], i) => {
    const col = document.createElement("div");
    col.className = "col";
    col.tabIndex = 0;
    col.dataset.tipTitle = y;
    col.dataset.tipBody = `${plural(k, "CVE")} published`;
    col.setAttribute("aria-label", `${y}: ${plural(k, "CVE")}`);
    const bar = document.createElement("div");
    bar.className = "bar";
    bar.style.height = `${(k / top) * 100}%`;
    if (k > 0 && (i === lastIdx || i === maxIdx)) {
      const cap = document.createElement("span");
      cap.className = "cap";
      cap.textContent = num(k);
      bar.append(cap);
    }
    col.append(bar);
    area.append(col);
    const lab = document.createElement("span");
    lab.textContent = years.length > 10 ? `’${y.slice(2)}` : y;
    xax.append(lab);
  });
}

function fitSegLabels() {
  requestAnimationFrame(() => {
    $$("#chart-sev .part").forEach((p) => {
      const l = $(".pl", p);
      l.classList.remove("hide");
      if (l.offsetWidth + 18 > p.clientWidth) l.classList.add("hide");
    });
  });
}

/* vendor response: day of the window on which each vendor shipped a fix */
function renderResponse() {
  const R = STATS.response;
  const tile = $(".t-resp");
  if (!R || !R.released || R.median == null) { tile.hidden = true; return; }
  $("#fig-ttf").innerHTML = `${Math.round(R.median)}<small>days</small>`;
  $("#fig-inwin").innerHTML = `${num(R.fixedBefore)}<small>/ ${num(R.released)}</small>`;
  $("#sub-inwin").textContent = `${Math.round((R.fixedBefore / R.released) * 100)}% patched before disclosure`;
  $("#fig-unp").textContent = num(R.unpatched);
  $("#sub-unp").textContent = `published at the deadline${R.fixedAfter ? `, ${num(R.fixedAfter)} fixed afterwards` : ""}`;
  const top = R.top;
  const xp = (d) => (d / top) * 100;
  const root = $("#chart-ttf");
  root.innerHTML = '<div class="sp-area"><div class="sp-after"></div><div class="sp-median"><span></span></div></div><div class="sp-axis"></div>';
  const area = $(".sp-area", root);
  $(".sp-after", root).style.left = `${xp(WINDOW_DAYS)}%`;
  const med = $(".sp-median", root);
  med.style.left = `${xp(R.median)}%`;
  $("span", med).textContent = `median ${Math.round(R.median)}`;
  const kinds = ["ok", "late", "emb"];
  if (R.points) {
    // few fixes: one dot per finding, stacked into lanes
    const lanes = [];
    const gap = top / 55;
    R.points.forEach(([day, kind, lab]) => {
      let lane = lanes.findIndex((last) => day - last >= gap);
      if (lane === -1) { lane = lanes.length; lanes.push(day); } else lanes[lane] = day;
      const dot = document.createElement("a");
      dot.className = `sp-dot ${kinds[kind]}`;
      dot.href = `#${String(lab).toLowerCase()}`;
      dot.style.left = `${xp(day)}%`;
      dot.style.bottom = `${8 + lane * 11}px`;
      dot.dataset.tipTitle = lab;
      dot.dataset.tipBody = `fixed on day ${day}${kind === 1 ? ", after disclosure" : kind === 2 ? ", still under embargo" : ""}`;
      dot.setAttribute("aria-label", `${lab}: fixed on day ${day}`);
      area.append(dot);
    });
    area.style.height = `${Math.max(3, lanes.length) * 11 + 26}px`;
  } else {
    // many fixes: 5-day histogram, stacked by outcome
    const maxBin = Math.max(1, ...R.bins.map(([, a, b, c]) => a + b + c));
    area.classList.add("hist");
    area.style.height = "120px";
    R.bins.forEach(([start, ok, late, emb]) => {
      const total = ok + late + emb;
      if (!total) return;
      const col = document.createElement("div");
      col.className = "sp-col";
      col.style.left = `${xp(start)}%`;
      col.style.width = `calc(${xp(5)}% - 2px)`;
      col.style.height = `${(total / maxBin) * 100}%`;
      col.tabIndex = 0;
      col.dataset.tipTitle = `Days ${start}–${start + 4}: ${plural(total, "fix")}`;
      col.dataset.tipBody = [ok && `${num(ok)} before disclosure`, emb && `${num(emb)} under embargo`, late && `${num(late)} after disclosure`].filter(Boolean).join(" · ");
      for (const [k, v] of [["ok", ok], ["emb", emb], ["late", late]]) {
        if (!v) continue;
        const seg = document.createElement("i");
        seg.className = k;
        seg.style.flexGrow = v;
        col.append(seg);
      }
      area.append(col);
    });
  }
  const axis = $(".sp-axis", root);
  for (let d = 0; d <= top; d += 15) {
    const t = document.createElement("span");
    t.style.left = `${xp(d)}%`;
    t.textContent = d === WINDOW_DAYS ? `${d} · deadline` : d;
    if (d === WINDOW_DAYS) t.className = "dl";
    axis.append(t);
  }
}

/* ---------- repositories ---------- */
function renderRepos() {
  const withRepo = (STATS.released.latest ?? []).filter((c) => SAFE.repo.test(c.repo ?? ""));
  if (withRepo[0]) $("#tree-name").textContent = withRepo[0].repo;
  $("#repo-list").innerHTML = withRepo.map((c) => `<a class="repo-row s-${esc(c.severity)}" href="https://github.com/${esc(c.repo)}" target="_blank" rel="noopener noreferrer">
    ${ICON.gh}<span class="r-text"><span class="rn">${esc(c.repo)}</span><span class="rd">${esc(c.title)} · ${fmtDate(c.date)}</span></span>
    <span class="rs"><span class="sev"><i></i>${esc(c.severity)}</span>${ICON.ext}</span></a>`).join("")
    || '<div class="wu-missing">No disclosures link a repository yet.</div>';
}

/* ================= reader (drawer) ================= */
let current = null;
let lastFocus = null;
let returnHash = "";
const CACHE = new Map();
const DETAILS = new Map();

function normalizeFull(raw) {
  const id = String(raw?.id ?? "").trim().toUpperCase();
  if (!SAFE.id.test(id)) return null;
  const repo = SAFE.repo.test(raw.repo ?? "") ? raw.repo : null;
  const branch = SAFE.ref.test(raw.branch ?? "") ? raw.branch : "main";
  const writeup = SAFE.path.test(raw.writeup ?? "") ? raw.writeup.replace(/^\/+/, "") : "README.md";
  const pocPath = SAFE.path.test(raw.pocPath ?? "") ? raw.pocPath.replace(/^\/+|\/+$/g, "") : "poc";
  const cvss = Number(raw.cvss) || 0;
  const type = String(raw.type || "Other");
  const c = {
    ...raw, id, repo, branch, writeup, pocPath, cvss, type, kind: "cve",
    severity: SEVERITIES.includes(raw.severity) ? raw.severity : severityOf(cvss),
    slug: id.toLowerCase(),
    trackingId: SAFE.tid.test(raw.trackingId ?? "") ? raw.trackingId : null,
    typeShort: CLASS_SHORT[type] || type,
    status: raw.status || "Disclosed",
    life: lifecycle(raw),
  };
  const blob = repo ? `https://github.com/${repo}/blob/${encPath(branch)}/${encPath(writeup)}` : null;
  c.links = {
    repo: repo ? `https://github.com/${repo}` : null,
    writeup: blob,
    raw: repo ? `https://raw.githubusercontent.com/${repo}/${encPath(branch)}/${encPath(writeup)}` : null,
    poc: httpsUrl(raw.pocUrl) || (raw.poc && repo ? `https://github.com/${repo}/tree/${encPath(branch)}/${encPath(pocPath)}` : null),
    nvd: id.startsWith("CVE-") ? `https://nvd.nist.gov/vuln/detail/${id}` : null,
    cwe: /^CWE-\d+$/.test(raw.cwe ?? "") ? `https://cwe.mitre.org/data/definitions/${raw.cwe.slice(4)}.html` : null,
  };
  return c;
}

async function loadDetails(row) {
  const path = `details/${row.date.slice(0, 4)}/${row.date}.json`;
  if (!DETAILS.has(path)) DETAILS.set(path, fetchJSON(path).catch((err) => { DETAILS.delete(path); throw err; }));
  const day = await DETAILS.get(path);
  const c = normalizeFull(day?.[row.id]);
  if (!c) throw new Error(`${row.id} is missing from ${path}`);
  return c;
}

function openDrawer(item) {
  if (current === item.slug) return;
  if (!current) lastFocus = document.activeElement;
  current = item.slug;
  if (item.kind === "embargo") renderEmbargoDrawer(item);
  else renderDrawerLoading(item);
  const d = $("#drawer");
  d.inert = false;
  document.body.classList.add("reading", "lock");
  $("#d-body").scrollTop = 0;
  requestAnimationFrame(() => $("#d-close").focus({ preventScroll: true }));
  document.title = `${item.kind === "embargo" ? item.trackingId : item.id} · BlackHalo Disclosures`;
  tick();
  if (item.kind !== "embargo") openReleased(item);
}

async function openReleased(row) {
  try {
    const c = row.full ?? (row.full = await loadDetails(row));
    if (current !== row.slug) return;
    renderDrawer(c);
    loadWriteup(c);
  } catch (err) {
    if (current !== row.slug) return;
    $("#d-loading")?.remove();
    $("#d-body").insertAdjacentHTML("beforeend", `<div class="wu-missing"><p>The details for ${esc(row.id)} couldn't be loaded (${esc(err.message)}). Reload the page to try again.</p></div>`);
  }
}

function closeDrawer(updateUrl = true) {
  if (!current) return;
  current = null;
  document.body.classList.remove("reading", "lock");
  $("#drawer").inert = true;
  document.title = "BlackHalo Disclosures";
  if (updateUrl) {
    const target = returnHash ? `#${returnHash}` : `${location.pathname}${location.search}`;
    try { history.replaceState(null, "", target); } catch { location.hash = returnHash; }
  }
  returnHash = "";
  if (lastFocus && document.contains(lastFocus)) lastFocus.focus({ preventScroll: true });
}

function renderDrawerLoading(row) {
  $("#d-crumbs").innerHTML = `Disclosures / <b>${esc(row.id)}</b>`;
  $("#d-body").innerHTML = `
    <div class="d-chips"><span class="chip s-${row.severity}"><i></i>${esc(row.severity)}</span><span class="chip mono">${esc(row.id)}</span></div>
    <h2 class="d-title" id="d-title">${esc(row.title)}</h2>
    <p class="d-sub">${esc(row.vendor)} · ${esc(row.product)}</p>
    <div class="skeleton" id="d-loading" role="status" aria-label="Loading details">${"<i></i>".repeat(7)}</div>`;
}

const HOT = { AV: "N", AC: "L", PR: "N", UI: "N", S: "C", C: "H", I: "H", A: "H" };
function renderDrawer(c) {
  const vec = describeVector(c.cvssVector);
  $("#d-crumbs").innerHTML = `Disclosures / <b>${esc(c.id)}</b>`;
  $("#d-body").innerHTML = `
    <div class="d-chips"><span class="chip s-${c.severity}"><i></i>${esc(c.severity)}</span><span class="chip">${esc(c.status)}</span><span class="chip mono">${esc(c.id)}</span></div>
    <h2 class="d-title" id="d-title">${esc(c.title)}</h2>
    <p class="d-sub">${esc(c.vendor)} · ${esc(c.product)}</p>
    ${c.summary ? `<p class="d-summary">${esc(c.summary)}</p>` : ""}
    <div class="d-actions">
      ${c.links.repo ? `<a class="btn btn-primary" href="${esc(c.links.repo)}" target="_blank" rel="noopener noreferrer">${ICON.gh}Open repository</a>` : ""}
      ${c.links.poc ? `<a class="btn btn-secondary" href="${esc(c.links.poc)}" target="_blank" rel="noopener noreferrer">${ICON.code}Proof of concept</a>` : ""}
      ${c.links.nvd ? `<a class="btn btn-secondary" href="${esc(c.links.nvd)}" target="_blank" rel="noopener noreferrer">${ICON.ext}NVD entry</a>` : ""}
    </div>
    <div class="score-card s-${c.severity}">
      <div class="score-big num">${c.cvss.toFixed(1)}<small>CVSS v3.1 · ${esc(c.severity)}</small></div>
      <div>${c.cvssVector ? `<div class="vector">${esc(c.cvssVector)}</div>` : '<div class="vector">No vector published</div>'}
        ${vec.length ? `<div class="metrics">${vec.map((m) => `<div class="metric${HOT[m.key] === m.code ? " hot" : ""}"><span>${esc(m.label)}</span><b>${esc(m.value)}</b></div>`).join("")}</div>` : ""}
      </div>
    </div>
    <dl class="d-meta">
      <div><dt>Published</dt><dd>${fmtDate(c.date)}</dd></div>
      <div><dt>Status</dt><dd>${esc(c.status)}</dd></div>
      <div><dt>Weakness</dt><dd>${c.links.cwe ? `<a href="${esc(c.links.cwe)}" target="_blank" rel="noopener noreferrer">${esc(c.cwe)}</a>` : esc(c.cwe || "—")} · ${esc(c.typeShort)}</dd></div>
      <div><dt>Vendor</dt><dd>${esc(c.vendor)}</dd></div>
      <div><dt>Product</dt><dd>${esc(c.product)}</dd></div>
      <div><dt>Repository</dt><dd>${c.links.repo ? `<a href="${esc(c.links.repo)}" target="_blank" rel="noopener noreferrer">${esc(c.repo)}</a>` : "Not linked"}</dd></div>
    </dl>
    ${c.life ? releasedTimeline(c) : ""}
    <div class="wu-head"><h3>Writeup</h3><span class="wu-src" id="wu-src"></span></div>
    <div id="wu" aria-live="polite"></div>`;
}

/** Lifecycle on one axis: report → acknowledgement → fix → deadline → disclosure. */
function timelineSVG({ max, deadlineDay, extFrom, extTo, events, label }) {
  const p = (d) => `${Math.min(100, Math.max(0, (d / max) * 100)).toFixed(2)}%`;
  const anchor = (d) => (d / max < 0.1 ? "start" : d / max > 0.9 ? "end" : "middle");
  return `<svg class="tl" width="100%" height="66" role="img" aria-label="${esc(label)}">
    <line class="tl-track" x1="0%" x2="100%" y1="33" y2="33"></line>
    ${extFrom != null ? `<line class="tl-ext" x1="${p(extFrom)}" x2="${p(extTo)}" y1="33" y2="33"></line>` : ""}
    <line class="tl-deadline" x1="${p(deadlineDay)}" x2="${p(deadlineDay)}" y1="23" y2="43"></line>
    ${events.map((ev) => `<g class="tl-ev ${ev.cls}"><title>${esc(ev.title)}</title><circle cx="${p(ev.day)}" cy="33" r="${ev.r || 5.5}"></circle>${ev.label ? `<text x="${p(ev.day)}" y="${ev.above ? 15 : 59}" text-anchor="${anchor(ev.day)}">${esc(ev.label)}</text>` : ""}</g>`).join("")}
  </svg>`;
}

function releasedTimeline(c) {
  const l = c.life;
  const fixedAfter = l.fixed && Date.parse(l.fixed) > l.releaseAt;
  const verdict = l.fixedDay == null
    ? `Disclosed unpatched on day ${l.releaseDay}`
    : fixedAfter ? `Fixed on day ${l.fixedDay}, ${l.fixedDay - l.releaseDay} days after disclosure` : `Fixed on day ${l.fixedDay} of ${l.total}`;
  const max = Math.max(l.total, l.releaseDay, l.fixedDay ?? 0);
  const events = [
    { day: 0, cls: "ev-rep", label: "Reported", title: `Reported ${fmtDate(new Date(l.reported).toISOString())}` },
    ...(l.ackDay != null ? [{ day: l.ackDay, cls: "ev-ack", r: 4, title: `Vendor acknowledged on day ${l.ackDay}` }] : []),
    ...(l.fixedDay != null ? [{ day: l.fixedDay, cls: fixedAfter ? "ev-late" : "ev-fix", above: true, label: `Fixed d${l.fixedDay}`, title: `Vendor fix ${fmtDate(l.fixed)} (day ${l.fixedDay})` }] : []),
    { day: l.releaseDay, cls: l.fixedDay == null ? "ev-full" : "ev-pub", label: `Disclosed d${l.releaseDay}`, title: `Published ${fmtDate(new Date(l.releaseAt).toISOString())}` },
  ];
  return `<div class="wu-head"><h3>Disclosure timeline</h3><span class="wu-src">${esc(verdict)}${c.trackingId ? ` · tracked as ${esc(c.trackingId)}` : ""}</span></div>
    ${timelineSVG({ max, deadlineDay: l.windowDays, extFrom: l.ext ? l.windowDays : null, extTo: l.total, events, label: verdict })}
    ${l.extensions.length ? `<ul class="ext-list">${l.extensions.map((x) => `<li><b>+${x.days} days</b>${esc(x.reason)}</li>`).join("")}</ul>` : ""}`;
}

function renderEmbargoDrawer(e) {
  const l = e.life, now = Date.now();
  const today = elapsedDays(l.reported, l.total, now);
  const events = [
    { day: 0, cls: "ev-rep", label: "Reported", title: `Reported ${fmtDate(new Date(l.reported).toISOString())}` },
    ...(l.ackDay != null ? [{ day: l.ackDay, cls: "ev-ack", r: 4, title: `Vendor acknowledged on day ${l.ackDay}` }] : []),
    ...(l.fixedDay != null ? [{ day: l.fixedDay, cls: "ev-fix", above: true, label: `Fixed d${l.fixedDay}`, title: `Vendor fix on day ${l.fixedDay}` }] : []),
    { day: today, cls: "ev-now", above: l.fixedDay == null || Math.abs(today - l.fixedDay) > l.total * 0.15, label: `Today d${today}`, title: "Today" },
    { day: l.total, cls: "ev-dead", label: `Release d${l.total}`, title: `Release ${whenFmt.format(l.releaseAt)}` },
  ];
  $("#d-crumbs").innerHTML = `Disclosure clock / <b>${esc(e.trackingId)}</b>`;
  $("#d-body").innerHTML = `
    <div class="d-chips"><span class="chip s-${e.severity}"><i></i>${esc(e.severity)}</span><span class="chip">${e.hold ? "Release paused" : "Under embargo"}</span>${e.cveAssigned ? '<span class="chip">CVE assigned</span>' : ""}<span class="chip mono">${esc(e.trackingId)}</span></div>
    <h2 class="d-title" id="d-title">${esc(e.type)} <span class="d-withheld">in a withheld product</span></h2>
    <p class="d-sub">${e.cwe ? `${esc(e.cwe)} · ` : ""}CVSS ${e.cvss.toFixed(1)} ${esc(e.severity)} · reported ${fmtDate(new Date(l.reported).toISOString())}</p>
    <div class="d-clock" data-until="${l.releaseAt}" data-kind="tone" data-eid="${e.slug}">
      <div class="dc-top"><span>Time until disclosure</span><span class="e-day" data-reported="${l.reported}" data-total="${l.total}">Day ${today} of ${l.total}</span></div>
      <div class="cd cd-xl" data-until="${l.releaseAt}" data-mode="full">${countdownHTML(l.releaseAt - now)}</div>
      <p class="dc-when">${e.hold
        ? "Automatic release is paused while disclosure is coordinated with the vendor."
        : `Vendor, product, CVE ID and writeup are published on <b>${esc(whenFmt.format(l.releaseAt))}</b>, whether a fix exists or not.`}</p>
      <div class="wbar wbar-lg" aria-hidden="true" data-reported="${l.reported}" data-total="${l.total}" data-window="${l.windowDays}" data-fix="${l.fixedDay ?? ""}">
        <span class="w-el"></span><span class="w-rem"></span>${l.ext ? '<span class="w-ext"></span>' : ""}${l.fixedDay != null ? '<span class="w-fix"></span>' : ""}
      </div>
    </div>
    <div class="wu-head"><h3>Timeline</h3><span class="wu-src">${l.fixedDay != null ? `Vendor fixed it on day ${l.fixedDay}` : l.ackDay != null ? `Acknowledged on day ${l.ackDay}, no fix yet` : "Waiting for the vendor to acknowledge"}</span></div>
    ${timelineSVG({ max: l.total, deadlineDay: l.windowDays, extFrom: l.ext ? l.windowDays : null, extTo: l.total, events, label: `Day ${today} of ${l.total}` })}
    ${l.extensions.length ? `<ul class="ext-list">${l.extensions.map((x) => `<li><b>+${x.days} days</b>${esc(x.reason)}</li>`).join("")}</ul>` : ""}
    <div class="wu-head"><h3>Withheld until release</h3></div>
    <ul class="withheld-list">${["Vendor", "Product", "CVE ID", "Technical writeup", "Proof of concept"].map((k) => `<li><span>${k}</span><span class="redact sm" aria-label="withheld"><span></span></span></li>`).join("")}</ul>
    <div class="policy-note"><b>Why the vendor is withheld.</b> BlackHalo lists every finding the day the vendor is notified, so the clock is public from the start. The product stays secret for ${l.windowDays} days, which is enough time to ship a patch. When the clock runs out, the full details are published, fixed or not.</div>`;
  const h = hashOf(e.slug);
  $$("#d-body .withheld-list .redact span").forEach((s, i) => (s.style.width = `${38 + ((h >> (i * 3)) % 50)}%`));
}

/* ---------- writeups from GitHub ---------- */
async function fetchText(url) {
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), SITE.fetchTimeoutMs);
  try {
    const res = await fetch(url, { signal: ctl.signal, cache: "no-cache", credentials: "omit" });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    if (/text\/html/i.test(res.headers.get("content-type") || "")) throw new Error("got HTML, not Markdown");
    return await res.text();
  } finally {
    clearTimeout(timer);
  }
}

const dirOf = (u) => u.slice(0, u.lastIndexOf("/") + 1);
async function loadWriteup(c) {
  const wu = $("#wu"), src = $("#wu-src");
  wu.innerHTML = `<div class="skeleton" role="status" aria-label="Loading writeup">${"<i></i>".repeat(9)}</div>`;
  let hit = CACHE.get(c.slug);
  if (!hit) {
    const sources = [];
    if (c.links.raw) sources.push({ url: c.links.raw, raw: dirOf(c.links.raw), blob: dirOf(c.links.writeup), label: `${c.repo} / ${c.writeup}`, href: c.links.writeup });
    const local = `${SITE.localWriteups}${c.id}.md`;
    sources.push({ url: local, raw: new URL(SITE.localWriteups, location.href).href, blob: `https://github.com/${SITE.repo}/blob/${SITE.branch}/${SITE.localWriteups}`, label: local, href: `https://github.com/${SITE.repo}/blob/${SITE.branch}/${local}` });
    for (const s of sources) {
      try {
        const text = await fetchText(s.url);
        if (text.trim()) { hit = { text, s }; break; }
      } catch { /* try the next source */ }
    }
    if (hit) CACHE.set(c.slug, hit);
  }
  if (current !== c.slug) return;
  if (!hit) {
    src.textContent = "";
    wu.innerHTML = `<div class="wu-missing"><p>${c.repo
      ? `The writeup couldn't be loaded from <b>${esc(c.repo)}</b>. The repository may still be private, or GitHub may be unreachable from this network.`
      : `No research repository is linked to ${esc(c.id)} yet.`}</p>
      ${c.links.writeup ? `<p><a href="${esc(c.links.writeup)}" target="_blank" rel="noopener noreferrer">Open the writeup on GitHub</a></p>` : ""}</div>`;
    return;
  }
  src.innerHTML = `${ICON.file}<a href="${esc(hit.s.href)}" target="_blank" rel="noopener noreferrer">${esc(hit.s.label)}</a>`;
  wu.replaceChildren(renderMarkdown(hit.text, hit.s));
}

function renderMarkdown(md, s) {
  const html = marked.parse(md, { gfm: true, async: false });
  const frag = DOMPurify.sanitize(html, {
    USE_PROFILES: { html: true },
    FORBID_TAGS: ["style", "form", "input", "button", "textarea", "select", "iframe"],
    FORBID_ATTR: ["style"],
    RETURN_DOM_FRAGMENT: true,
  });
  const root = document.createElement("div");
  root.className = "prose";
  root.append(frag);
  if (root.firstElementChild?.tagName === "H1") root.firstElementChild.remove();
  $$("h1, h2, h3, h4", root).forEach((h) => { h.removeAttribute("id"); h.dataset.anchor = slugify(h.textContent); });
  $$("img", root).forEach((img) => {
    const srcAttr = img.getAttribute("src") || "";
    if (srcAttr && !/^(https?:|data:)/i.test(srcAttr)) img.src = new URL(srcAttr, s.raw).href;
    img.loading = "lazy";
    img.decoding = "async";
    if (!img.hasAttribute("alt")) img.alt = "";
  });
  $$("a[href]", root).forEach((a) => {
    const href = a.getAttribute("href");
    if (href.startsWith("#")) { a.dataset.jump = decodeURIComponent(href.slice(1)).toLowerCase(); return; }
    if (!/^[a-z][a-z0-9+.-]*:/i.test(href)) a.href = new URL(href, s.blob).href;
    if (/^https?:/i.test(a.href)) { a.target = "_blank"; a.rel = "noopener noreferrer"; }
  });
  $$("table", root).forEach((t) => {
    const head = t.tHead;
    if (head && !head.textContent.trim()) head.remove(); // GitHub-style key/value tables use an empty header row
    const w = document.createElement("div");
    w.className = "table-wrap";
    t.replaceWith(w);
    w.append(t);
  });
  $$("pre", root).forEach((pre) => {
    const w = document.createElement("div");
    w.className = "codewrap";
    pre.replaceWith(w);
    const b = document.createElement("button");
    b.type = "button";
    b.className = "copy";
    b.textContent = "Copy";
    b.dataset.copy = "";
    w.append(pre, b);
  });
  return root;
}

/* ---------- routing: #cve-2026-48210 or #bh-2026-0021 opens the reader ---------- */
async function route(e) {
  const h = decodeURIComponent(location.hash.slice(1)).toLowerCase();
  let c = BY_SLUG.get(h) || EMB_BY_SLUG.get(h);
  const looksLikeId = /^(cve-\d{4}-\d{4,}|bh-\d{4}-\d{3,})$/.test(h);
  if (!c && looksLikeId && SHARDS.first) { await SHARDS.first; c = BY_SLUG.get(h) || EMB_BY_SLUG.get(h); }
  if (!c && looksLikeId && !SHARDS.complete) {
    // an older disclosure: wait for the remaining years to load
    toast(`Looking up ${h.toUpperCase()}…`);
    while (!SHARDS.done && !SHARDS.complete) await new Promise((r) => setTimeout(r, 100));
    if (SHARDS.done) await SHARDS.done;
    if (decodeURIComponent(location.hash.slice(1)).toLowerCase() !== h) return;
    c = BY_SLUG.get(h) || EMB_BY_SLUG.get(h);
  }
  if (c) {
    if (e?.oldURL) {
      const old = decodeURIComponent(new URL(e.oldURL).hash.slice(1)).toLowerCase();
      if (!BY_SLUG.has(old) && !EMB_BY_SLUG.has(old)) returnHash = old;
    }
    if (c.kind === "cve" && c.trackingId && h === c.trackingId.toLowerCase()) toast(`${c.trackingId} has been released as ${c.id}`);
    openDrawer(c);
    return;
  }
  if (looksLikeId) toast(`${h.toUpperCase()} isn't in this repository`);
  if (current) closeDrawer(false);
}

/* ---------- command palette ---------- */
const pal = $("#palette"), palQ = $("#pal-q"), palList = $("#pal-list");
let palItems = [], palIdx = 0;
function scoreMatch(c, terms) {
  const hay = c.kind === "embargo" ? c.hay : hayOf(c);
  let sc = 0;
  for (const t of terms) {
    if (!hay.includes(t)) return 0;
    if ((c.id || c.trackingId).toLowerCase().includes(t)) sc += 4;
    if (c.kind === "cve" && c.title.toLowerCase().includes(t)) sc += 2;
    if (c.kind === "cve" && `${c.vendor} ${c.product}`.toLowerCase().includes(t)) sc += 2;
    sc += 1;
  }
  return sc;
}
function renderPalette() {
  const terms = palQ.value.toLowerCase().split(/\s+/).filter(Boolean);
  if (terms.length) {
    const top = [];
    for (const pool of [EMB, IDX]) {
      for (const c of pool) {
        const s = scoreMatch(c, terms);
        if (!s) continue;
        if (top.length < 8) { top.push([c, s]); top.sort((a, b) => b[1] - a[1]); }
        else if (s > top[7][1]) { top[7] = [c, s]; top.sort((a, b) => b[1] - a[1]); }
      }
    }
    palItems = top.map(([c]) => c);
  } else {
    palItems = [...EMB.slice(0, 4), ...IDX.slice(0, 4)];
  }
  palIdx = 0;
  palList.innerHTML = palItems.length
    ? palItems.map((c, i) => {
      const embargoed = c.kind === "embargo";
      return `<li role="option" id="po-${i}" aria-selected="${i === 0}"><a class="s-${c.severity}" href="#${c.slug}" tabindex="-1"><i></i><span class="pid">${esc(embargoed ? c.trackingId : c.id)}</span><span class="pt">${embargoed ? `${esc(c.typeShort)} <span class="withheld">· vendor withheld · ${shortLeft(c.life.releaseAt - Date.now())} left</span>` : esc(c.title)}</span><span class="ps">${c.cvss.toFixed(1)}</span></a></li>`;
    }).join("")
    : `<li class="pal-empty">No disclosures match “${esc(palQ.value)}”.</li>`;
  palQ.setAttribute("aria-activedescendant", palItems.length ? "po-0" : "");
}
function movePalette(d) {
  if (!palItems.length) return;
  palIdx = (palIdx + d + palItems.length) % palItems.length;
  $$("li[role=option]", palList).forEach((li, i) => li.setAttribute("aria-selected", String(i === palIdx)));
  palQ.setAttribute("aria-activedescendant", `po-${palIdx}`);
  $(`#po-${palIdx}`)?.scrollIntoView({ block: "nearest" });
}
function openPalette() {
  if ((!IDX.length && !EMB.length) || pal.open) return;
  palQ.value = "";
  renderPalette();
  pal.showModal();
  palQ.focus();
}
palQ.addEventListener("input", debounce(renderPalette, 80));
palQ.addEventListener("keydown", (e) => {
  if (e.key === "ArrowDown") { e.preventDefault(); movePalette(1); }
  else if (e.key === "ArrowUp") { e.preventDefault(); movePalette(-1); }
  else if (e.key === "Enter" && palItems[palIdx]) { e.preventDefault(); pal.close(); location.hash = palItems[palIdx].slug; }
});
palList.addEventListener("click", (e) => { if (e.target.closest("a")) pal.close(); });
pal.addEventListener("click", (e) => { if (e.target === pal) pal.close(); });
$("#open-palette").addEventListener("click", openPalette);

/* ---------- tooltip ---------- */
const tip = $("#tip");
function placeTip(x, y) {
  const r = tip.getBoundingClientRect();
  tip.style.left = `${Math.min(x + 14, innerWidth - r.width - 8)}px`;
  tip.style.top = `${Math.min(y + 14, innerHeight - r.height - 8)}px`;
}
function showTip(el, x, y) {
  $(".tt", tip).textContent = el.dataset.tipTitle || "";
  $(".tb", tip).textContent = el.dataset.tipBody || "";
  tip.classList.add("on");
  placeTip(x, y);
}
const hideTip = () => tip.classList.remove("on");
document.addEventListener("pointerover", (e) => { const el = e.target.closest?.("[data-tip-title]"); if (el) showTip(el, e.clientX, e.clientY); });
document.addEventListener("pointermove", (e) => { if (tip.classList.contains("on")) placeTip(e.clientX, e.clientY); });
document.addEventListener("pointerout", (e) => { const el = e.target.closest?.("[data-tip-title]"); if (el && !el.contains(e.relatedTarget)) hideTip(); });
document.addEventListener("focusin", (e) => { const el = e.target.closest?.("[data-tip-title]"); if (el) { const r = el.getBoundingClientRect(); showTip(el, r.left + r.width / 2, r.top - 10); } else hideTip(); });
addEventListener("scroll", hideTip, { passive: true });

/* ---------- toast + clipboard ---------- */
let toastTimer;
function toast(msg) {
  const t = $("#toast");
  t.textContent = msg;
  t.classList.add("on");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove("on"), 2600);
}
async function copy(text, ok, fail) {
  try { await navigator.clipboard.writeText(text); toast(ok); return true; }
  catch { toast(fail); return false; }
}

/* ---------- one ticker drives every countdown, colour, bar and relative time on screen ---------- */
function tick() {
  const now = Date.now();
  $$("[data-until]").forEach((el) => {
    const ms = +el.dataset.until - now;
    const e = el.dataset.eid ? EMB_BY_SLUG.get(el.dataset.eid) : null;
    if (el.dataset.kind === "tone") {
      el.style.setProperty("--cc", e?.hold ? "var(--ink-3)" : clockColor(ms));
      el.dataset.state = e ? clockState(e, now) : ms <= 0 ? "due" : ms < DAY ? "final" : ms < 7 * DAY ? "soon" : "running";
    }
    const mode = el.dataset.mode;
    if (mode === "full") el.innerHTML = countdownHTML(ms);
    else if (mode === "short") el.textContent = ms > 0 ? shortLeft(ms) : "now";
    else if (mode === "state") {
      el.textContent = e?.hold ? "release paused while disclosure is coordinated"
        : ms <= 0 ? "deadline reached · details publish within the hour"
        : "until vendor and product are disclosed";
    }
  });
  $$(".wbar").forEach((b) => layoutBar(b, now));
  $$(".e-day").forEach((el) => { el.textContent = `Day ${elapsedDays(+el.dataset.reported, +el.dataset.total, now)} of ${el.dataset.total}`; });
  $$("time[data-rel]").forEach((el) => { el.textContent = relTime(+el.dataset.rel, now); });
}
function startTicker() {
  if (!EMB.length) return;
  tick();
  let timer = setInterval(tick, 1000);
  document.addEventListener("visibilitychange", () => {
    clearInterval(timer);
    if (!document.hidden) { tick(); timer = setInterval(tick, 1000); }
  });
}

/* ---------- global events ---------- */
$("#d-close").addEventListener("click", () => closeDrawer());
$("#scrim").addEventListener("click", () => closeDrawer());
$("#d-copy").addEventListener("click", () => copy(location.href, "Link copied", "Couldn't copy. Use the address bar instead."));
$("#d-body").addEventListener("click", async (e) => {
  const jump = e.target.closest("a[data-jump]");
  if (jump) {
    e.preventDefault();
    $(`[data-anchor="${CSS.escape(jump.dataset.jump)}"]`, $("#d-body"))?.scrollIntoView({ behavior: "smooth", block: "start" });
    return;
  }
  const btn = e.target.closest("button[data-copy]");
  if (btn) {
    const ok = await copy($("pre", btn.parentElement).innerText, "Code copied", "Couldn't copy. Select the code instead.");
    if (ok) { btn.textContent = "Copied"; setTimeout(() => (btn.textContent = "Copy"), 1500); }
  }
});

document.addEventListener("keydown", (e) => {
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
    e.preventDefault();
    pal.open ? pal.close() : openPalette();
    return;
  }
  if (e.key === "/" && !isTyping(e.target) && !pal.open) { e.preventDefault(); openPalette(); return; }
  if (!current || pal.open) return;
  if (e.key === "Escape") { e.preventDefault(); closeDrawer(); return; }
  if (e.key === "Tab") {
    const f = $$('a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])', $("#drawer")).filter((x) => x.offsetParent !== null);
    if (!f.length) return;
    const first = f[0], last = f[f.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  }
});
addEventListener("hashchange", route);
addEventListener("resize", debounce(() => { fitSegLabels(); if (EMB.length) renderForecast(Date.now()); }, 150));

wireBoard();
wireIndex();
init();
